const rows = $input.all().map(i => i.json);

const config = {};

for (const row of rows) {
  const key = String(row.campo || '').trim();
  const value = row.valor ?? '';

  if (key) config[key] = value;
}

function splitList(value) {
  return String(value || '')
    .split(',')
    .map(v => v.trim())
    .filter(Boolean);
}

// Histórico manual de mayo 2026.
// Puedes sobrescribirlo desde la Sheet con la fila feed_url si quieres otro mes.
const feedUrlHistorico = 'https://contrataciondelsectorpublico.gob.es/sindicacion/sindicacion_643/licitacionesPerfilesContratanteCompleto3_202605.zip';

return [{
  json: {
    feed_url: config.feed_url && String(config.feed_url).includes('.zip')
      ? String(config.feed_url).trim()
      : feedUrlHistorico,

    keywords: splitList(config.keywords),
    exclude_keywords: splitList(config.exclude_keywords),
    provincias: splitList(config.provincia),
    cpvs: splitList(config.cpv),

    importe_min: Number(config.importe_min || 0),
    email_destino: String(config.email_destino || '').trim(),
    max_resultados: Number(config.max_resultados || 25),
    solo_abiertas: String(config.solo_abiertas || '').toLowerCase() === 'sí',
    frecuencia: String(config.frecuencia || 'diaria').trim(),

    // Para el histórico, añade estas filas opcionales en la Sheet:
    // data_desde | 1
    // data_hasta | 6
    data_desde: Number(config.data_desde || 1),
    data_hasta: Number(config.data_hasta || 6)
  }
}];

const config = $('Normalizar configuración').first().json;
const allInputs = $input.all();

const keywords = config.keywords || [];
const excludeKeywords = config.exclude_keywords || [];
const provincias = config.provincias || [];
const cpvs = config.cpvs || [];
const maxResultados = Number(config.max_resultados || 100);

function textOf(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (value._) return value._;
  if (value['#text']) return value['#text'];
  return JSON.stringify(value);
}

function normalizeCpv(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^0-9]/g, '');
}

function getEntries(xml) {
  const feed = xml.feed || xml;
  let entries = feed.entry || [];

  if (!entries) return [];
  if (!Array.isArray(entries)) entries = [entries];

  return entries;
}

const resultados = [];

for (const input of allInputs) {
  const entries = getEntries(input.json);

  for (const entry of entries) {
    const title = textOf(entry.title);
    const summary = textOf(entry.summary);
    const id = textOf(entry.id);
    const updated = textOf(entry.updated);
    const content = textOf(entry.content);

    let link = '';

    if (Array.isArray(entry.link)) {
      const alt = entry.link.find(l => l.rel === 'alternate') || entry.link[0];
      link = alt?.href || '';
    } else if (entry.link) {
      link = entry.link.href || '';
    }

    const texto = JSON.stringify(entry).toLowerCase();
    const textoCpvNormalizado = normalizeCpv(texto);

    const pasaKeyword =
      keywords.length === 0 ||
      keywords.some(k => texto.includes(String(k).toLowerCase()));

    const pasaExclusion =
      excludeKeywords.length === 0 ||
      !excludeKeywords.some(k => texto.includes(String(k).toLowerCase()));

    const pasaProvincia =
      provincias.length === 0 ||
      provincias.some(p => texto.includes(String(p).toLowerCase()));

    const pasaCpv =
      cpvs.length === 0 ||
      cpvs.some(cpv => {
        const cpvNormalizado = normalizeCpv(cpv);
        return cpvNormalizado && textoCpvNormalizado.includes(cpvNormalizado);
      });

    if (pasaKeyword && pasaExclusion && pasaProvincia && pasaCpv) {
      resultados.push({
        id,
        title,
        summary,
        updated,
        link,
      });
    }
  }
}

const unicos = Array.from(
  new Map(
    resultados.map(r => [
      r.id || r.link || r.title,
      r,
    ])
  ).values()
);

const salida = unicos.slice(0, maxResultados);

if (salida.length === 0) {
  return [{
    json: {
      id: 'sin-resultados',
      title: 'No se encontraron licitaciones con los filtros actuales',
      summary: 'Prueba ampliando keywords, quitando CPV o dejando provincia vacía.',
      updated: new Date().toISOString(),
      link: '',
    }
  }];
}

return salida.map(r => ({ json: r }));

const items = $input.all();
const config = $('Normalizar configuración').first().json;

const rows = items.map((item, index) => {
  const r = item.json;
  return `
    <tr>
      <td>${index + 1}</td>
      <td><strong>${r.title || ''}</strong><br>${r.summary || ''}</td>
      <td><a href="${r.link || '#'}">Ver licitación</a></td>
      <td>${r.updated || ''}</td>
    </tr>
  `;
}).join('');

const html = `
<h2>Nuevas licitaciones encontradas</h2>
<p>Se han encontrado <strong>${items.length}</strong> licitaciones.</p>

<table border="1" cellpadding="8" cellspacing="0">
  <thead>
    <tr>
      <th>#</th>
      <th>Licitación</th>
      <th>Enlace</th>
      <th>Fecha</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
`;

return [{
  json: {
    email_destino: config.email_destino,
    subject: `Alertas licitaciones: ${items.length} resultados`,
    html,
  }
}];

const item = $input.first();
const binaries = item.binary || {};
const config = $('Normalizar configuración').first().json;

const desde = Number(config.data_desde || 1);
const hasta = Number(config.data_hasta || 6);

return Object.keys(binaries)
  .filter(key => key.startsWith('data'))
  .slice(desde, hasta)
  .map(key => ({
    json: {
      binary_field: key,
      data_desde: desde,
      data_hasta: hasta,
    },
    binary: {
      [key]: binaries[key],
    },
  }));

const nuevas = $('Filtrar licitaciones').all();
const enviadas = $input.all();

const idsEnviados = new Set(
  enviadas
    .map(i => i.json.id_licitacion)
    .filter(Boolean)
);

const resultado = nuevas.filter(item => {
  const id = item.json.id;
  return id && !idsEnviados.has(id);
});

return resultado;
